    "INSERT INTO ACTIVITY (USER_ID, SESSION_ID, ACTIVITY_DATE, ACTIVITY_TYPE) VALUES (NULL, 1, '2019-06-28', 'OPEN_SESSION');",
    "INSERT INTO ACTIVITY (USER_ID, SESSION_ID, ACTIVITY_DATE, ACTIVITY_TYPE) VALUES (1, 2, '2019-07-01', 'OPEN_SESSION');"
